new:
$batchRecipProof=Track-File (Join-Path $root 'build/khc-reciprocal-batch-20261002/report.json') 'reciprocal-batch-numeric-proof'
if($batchRecipProof.before_sha256 -cne 'A58898BA7716CE836B921FA04E3152718BB5D96B53FA279EC5EB27FAD69D3DD4'){throw 'Reciprocal batch proof SHA'}
$batchRecipJson=Get-Content -LiteralPath $batchRecipProof.path -Raw|ConvertFrom-Json
if($batchRecipJson.status -cne 'reciprocal_batch_numeric_verified_not_codec_or_timing' -or $batchRecipJson.failure -or $batchRecipJson.timing_used -or $batchRecipJson.checks.Count -ne 32 -or $batchRecipJson.invocations.Count -ne 87 -or $batchRecipJson.identities.Count -ne 28 -or $batchRecipJson.owned_tmp_or_reparse -ne 0 -or !$batchRecipJson.features.avx2_available -or $batchRecipJson.summaries.Count -ne 4){throw 'Reciprocal batch numeric matrix'}
$batchRecipMatrix=@($batchRecipJson.summaries|ForEach-Object {"$($_.opt)/$($_.backend)"}|Sort-Object)
if(($batchRecipMatrix -join ',') -cne '2/avx2,2/scalar,3/avx2,3/scalar'){throw 'Reciprocal batch matrix'}
foreach($item in $batchRecipJson.summaries){
    $counts=$item.summary
    if($counts.records -ne 9293629 -or $counts.matched -ne 9293629 -or $counts.batches -ne 2323408 -or $counts.compact -ne 8398832 -or $counts.certificate_fallback -ne 0 -or $counts.fingerprint_u64 -cne 'f02dbdcb00adbe1d'){throw 'Reciprocal batch coverage'}
    if(($counts|ConvertTo-Json -Compress) -cne ($batchRecipJson.summaries[0].summary|ConvertTo-Json -Compress)){throw 'Reciprocal batch summary differs'}
}
foreach($call in $batchRecipJson.invocations){
    $expectedExit=if($call.argv.Count -eq 0 -or ($call.argv.Count -gt 2 -and $call.argv[0] -ceq 'query' -and $call.argv[2] -ceq '-1')){2}else{0}
    if($call.exit -ne $expectedExit -or ($expectedExit -eq 0 -and $call.stderr) -or ($expectedExit -ne 0 -and (!$call.stderr -or $call.stdout))){throw 'Reciprocal batch child failure'}
}
$recipFullProof=Track-File (Join-Path $root 'build/khc-reciprocal-codec-20261002/report.json') 'reciprocal-codec-full-proof'
if($recipFullProof.before_sha256 -cne '22C7D3364743D2FD962A330BCA5EC9BBE2DF4EC6E1603F8BB4ED655FE0D645BE'){throw 'Reciprocal codec full SHA'}
$recipFullJson=Get-Content -LiteralPath $recipFullProof.path -Raw|ConvertFrom-Json
if($recipFullJson.status -cne 'reciprocal_codec_correctness_and_size_passed_not_timed' -or $recipFullJson.failure -or $recipFullJson.timing_used -or $recipFullJson.formal_performance_retried -or $recipFullJson.observer_gate_changed -or $recipFullJson.checks.Count -ne 51 -or $recipFullJson.invocations.Count -ne 86 -or $recipFullJson.identities.Count -ne 466 -or $recipFullJson.validated_base_records -ne 841 -or $recipFullJson.validated_numeric_records -ne 28 -or $recipFullJson.owned_tmp_pdb_reparse -ne 0 -or $recipFullJson.peak_owned_bytes_checked -gt 8MB){throw 'Reciprocal codec full matrix'}
$recipOrdinary=@($recipFullJson.identities|Where-Object {$_.role -ceq 'native-codec' -and $_.path -ceq $candidate.path -and $_.before_sha256 -ceq $candidate.before_sha256 -and $_.bytes -eq 241152})
if($recipOrdinary.Count -ne 1){throw 'Candidate not reciprocal ordinary codec'}
$recipRefusals=@($recipFullJson.invocations|Where-Object exit -ne 0)
if($recipRefusals.Count -ne 8 -or @($recipRefusals|Where-Object {$_.exit -ne 1 -or !$_.stderr -or $_.stdout}).Count -or @($recipFullJson.invocations|Where-Object {$_.exit -eq 0 -and $_.stderr}).Count){throw 'Reciprocal codec child results'}
foreach($variant in @('native','checked','scalar','scalar-checked')){
    $variantExe=Join-Path $root "build/khc-reciprocal-codec-20261002/codec-$variant.exe"
    foreach($caseName in @('empty','single','all_bytes','repeated','periodic','seeded_random','fixed')){
        if(@($recipFullJson.checks|Where-Object {$_ -ceq "$caseName-$variant-full-frame-summary-restore"}).Count -ne 1){throw 'Reciprocal full case missing'}
    }
    $variantCalls=@($recipFullJson.invocations|Where-Object {$_.program -ceq $variantExe -and $_.exit -eq 0})
    $expectedCount=if($variant -ceq 'native'){21}else{14}
    if($variantCalls.Count -ne $expectedCount){throw 'Reciprocal variant child count'}
}
$countedPath=Join-Path $root 'build/khc-reciprocal-codec-20261002/codec-counted.exe'
$countedCalls=@($recipFullJson.invocations|Where-Object {$_.program -ceq $countedPath -and $_.exit -eq 0})
if($countedCalls.Count -ne 2 -or (($countedCalls|ForEach-Object {$_.argv[0]}) -join ',') -cne 'encode,decode'){throw 'Reciprocal counted call order'}
$recipDiagnostic=@($countedCalls|ForEach-Object {($_.stdout.Trim().Split("`n"))[1]|ConvertFrom-Json})
if(($recipDiagnostic[0]|ConvertTo-Json -Compress) -cne ($recipDiagnostic[1]|ConvertTo-Json -Compress)){throw 'Reciprocal counted direction differs'}
$rd=$recipDiagnostic[0]
if($rd.compact_groups -ne 12892624 -or $rd.fallback_groups -ne 0 -or $rd.compact_option_bytes -ne 40 -or $rd.plain_array_bytes -ne 32 -or $rd.legacy_array_bytes -ne 96 -or $rd.node_bytes -ne 12 -or $rd.node_count -ne 917497 -or $rd.logical_node_storage_bytes -ne 11009964 -or $rd.light_prediction_bytes -ne 24 -or $rd.scheduler_prediction_bytes -ne 608){throw 'Reciprocal kernel/layout mismatch'}
# このfull proofだけは、比較後に削除済みのscratchをpersistent fileと混同しない。
$ledger=@($recipFullJson.compared_output_records)
if($ledger.Count -ne 72 -or @($ledger.role|Sort-Object -Unique).Count -ne 72 -or @($ledger|Where-Object deleted).Count -ne 71){throw 'Reciprocal compared output ledger coverage'}
$owner=[IO.Path]::GetDirectoryName($recipFullProof.path)
$scratchPaths=@((Join-Path $owner 'scratch.frame'),(Join-Path $owner 'scratch.restore'))
$retainedPath=Join-Path $owner 'fixed-native.frame'
$recipSuccessful=@($recipFullJson.invocations|Where-Object {$_.exit -eq 0 -and $_.program -cne 'C:/Users/IMT/.rustup/toolchains/1.98.1-x86_64-pc-windows-msvc/bin/rustc.exe'})
if($recipSuccessful.Count -ne 72){throw 'Reciprocal successful codec output count'}
foreach($row in $ledger){
    if(!$row.full_bytes_compared -or $row.sha256 -cne $row.reference_sha256 -or $row.bytes -lt 0){throw 'Reciprocal full-byte ledger certificate'}
    $reference=Track-File $row.compared_against 'reciprocal-compared-reference'
    if($reference.before_bytes -ne $row.bytes -or $reference.before_sha256 -cne $row.reference_sha256){throw 'Reciprocal comparison reference changed'}
    if($row.delete_requested){
        if(!$row.deleted -or $row.path -cnotin $scratchPaths -or (Test-Path -LiteralPath $row.path)){throw 'Reciprocal deleted output not exact owned scratch'}
    }else{
        if($row.deleted -or $row.path -cne $retainedPath -or $row.role -cne 'retained-fixed-native-frame' -or $row.bytes -ne 483496 -or $row.sha256 -cne 'CF62CD2324B4CF889CDDDB25C9508C28E4BD4D24217B93BB7D4FF9318C3EAD12'){throw 'Reciprocal retained output mismatch'}
        $retained=Track-File $row.path 'reciprocal-retained-frame'
        if($retained.before_bytes -ne $row.bytes -or $retained.before_sha256 -cne $row.sha256){throw 'Reciprocal retained frame changed'}
    }
}
foreach($outputPath in @($scratchPaths)+@($retainedPath)){
    if(@($ledger|Where-Object path -ceq $outputPath).Count -ne @($recipSuccessful|Where-Object {$_.argv.Count -eq 3 -and $_.argv[2] -ceq $outputPath}).Count){throw 'Reciprocal output ledger/CLI path cardinality differs'}
}
$recipHistoryJson=($recipFullJson|ConvertTo-Json -Depth 12)|ConvertFrom-Json
$recipHistoryJson.PSObject.Properties.Remove('compared_output_records')
$report['reciprocal_proofs']=[ordered]@{numeric=$batchRecipProof;full=$recipFullProof;diagnostic=$rd;deleted_outputs_not_persistent_evidence=71;retained_output_count=1}
$null=Track-File (Join-Path $PSScriptRoot '../RECIPROCAL_CODEC_PERFORMANCE_CONTRACT_20261002.md') 'reciprocal-performance-contract'

$report['historical_budget_guard_repairs']=[Collections.Generic.List[object]]::new()
